import re

with open('app.js', 'r', encoding='utf-8') as f:
    js = f.read()

with open('new_icon.txt', 'r', encoding='utf-8') as f:
    new_icon = f.read().strip()

# Find the end of EXERCISES dictionary
old_code = """    'Slant Board Squat': '<svg width="100%" height="100%" viewBox="0 0 117 205"><mask id="mask_Slant_Board_Squat"><image width="117" height="205" href="data:image/png;base64," /></mask><rect width="117" height="205" fill="currentColor" mask="url(#mask_Slant_Board_Squat)" /></svg>'
};"""

new_code = f"""    'Slant Board Squat': '<svg width="100%" height="100%" viewBox="0 0 117 205"><mask id="mask_Slant_Board_Squat"><image width="117" height="205" href="data:image/png;base64," /></mask><rect width="117" height="205" fill="currentColor" mask="url(#mask_Slant_Board_Squat)" /></svg>',
{new_icon}
}};"""

js = js.replace(old_code, new_code)

with open('app.js', 'w', encoding='utf-8') as f:
    f.write(js)
